// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;

    function setUp() public { c = new Reentrancy_bonus(); }

    function testFuzz_property(address recipientAddr, uint256 fundAmount) public {
        fundAmount = bound(fundAmount, 1, 1 ether);

        Receiver r = new Receiver();

        vm.deal(address(this), fundAmount);

        Setter helper = new Setter(address(c));

        bool ok1;
        try c.withdrawReward(address(r)) {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        bool ok2;
        try c.withdrawReward(address(r)) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(!(ok1 && !ok2));
    }
}

contract Receiver {
    receive() external payable {}
}

contract Setter {
    Reentrancy_bonus c;
    constructor(address _c) { c = Reentrancy_bonus(_c); }
    function callGetFirstWithdrawalBonus(address recipient) external {
        c.getFirstWithdrawalBonus(recipient);
    }
}
